<template><scroll-view scroll-y><view class="card"><view class="section-title">菌淘商城</view><view v-for="p in products" :key="p.id" class="product"><view><strong>{{ p.name }}</strong><p>{{ p.description }}</p><text>￥{{ p.price }}</text></view><button @tap="buy(p)">购买</button></view></view></scroll-view></template>
<script setup>import { ref,onMounted } from 'vue'; import { api } from '@/api/index'; const products=ref([]); onMounted(async()=>{ products.value=await api.products() }); async function buy(p){ const order=await api.createOrder({items:[{productId:p.id, quantity:1}], pointsUsed:0}); const params=await api.payParams({orderNo:order.orderNo}); uni.requestPayment({...params, success(){uni.showToast({title:'支付成功'})}, fail(){uni.showToast({title:'已生成订单', icon:'none'})}}) }</script>
<style scoped>.product{display:flex;justify-content:space-between;gap:20rpx;background:#f8fcf9;border-radius:18rpx;padding:20rpx;margin-top:18rpx}.product p{color:#6b7f71;font-size:22rpx}.product text{color:#e47b17;font-weight:800}.product button{background:#08a64b;color:#fff;border-radius:999rpx;align-self:center}</style>
